package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sync"
)

// NodeInfo holds the node ID and all other node IDs
type NodeInfo struct {
	ID           int
	OtherNodes   map[int]int
}

// TicketMsg represents an issue request
type IssueMsg struct {
	MsgID json.Number `json:"msg_id"`
}

// IssuedMsg represents the response to an issue request
type IssuedMsg struct {
	InReplyTo    json.Number `json:"in_reply_to"`
	Ticket       interface{} `json:"ticket"`
}

// Message is a JSON message from maelstrom
type Message struct {
	ReqID int      `json:"req_id"`
	Type  string   `json:"type"`
	Body  interface{ json.Unmarshal(data []byte) error }
}

var (
	nodeNum       int // our node ID
	nodes         []int // all node IDs
	ticketCounter sync.Map // atomic ticket counter across all nodes
	nextTicket    int      // local index for generating unique tickets per round
	mu            sync.Mutex
)

func (m *Message) UnmarshalJSON(data []byte) error {
	return json.Unmarshal(data, m.Body)
}

func main() {
	ctx := &maelstromCtx{node: nil, initDone: false, ready: false}

	// Handle init message first - get our node ID and all other node IDs
	if err := handleInit(ctx); err != nil {
		log.Fatalf("init error: %v", err)
	}
	fmt.Fprintf(os.Stderr, "init done, myID=%d\n", nodeNum)

	// Now start a goroutine to handle requests from maelstrom library
	go func() {
		for {
			line, err := os.Stdin.ReadLine()
			if err != nil {
				break
			}
			var msg Message
			err = json.Unmarshal([]byte(line), &msg)
			if err != nil {
				log.Fatalf("unmarshal error: %v", err)
			}
			handleRequest(ctx, msg)
		}
	}()

	// Start the node - wait forever for requests
	ctx.run()
}

func handleInit(ctx *maelstromCtx) error {
	line, _ := os.Stdin.ReadLine()
	if line == "" {
		return nil
	}
	var initMsg struct {
		MyID  json.Number `json:"my_id"`
		Nodes []int       `json:"nodes"`
	}
	json.Unmarshal([]byte(line), &initMsg)
	nodeNum = int(initMsg.MyID.Int64())
	nodes = initMsg.Nodes

	ticketCounter.Set(0)
	nextTicket = 1

	return nil
}

func handleRequest(ctx *maelstromCtx, msg Message) {
	body := msg.Body.([]byte)
	msgType := msg.Type

	switch msgType {
	case "issue":
		// Handle issue request - generate a unique ticket for all nodes
		reply := handleIssue(body, ctx)
		ctx.reply(reply)
	default:
		log.Printf("unknown message type: %s", msgType)
	}
}

func handleIssue(body []byte, ctx *maelstromCtx) interface{} {
	var req IssueMsg
	json.Unmarshal(body, &req)

	msgID, _ := req.MsgID.Int64()
	ticketCounter.Set(int(msgID))

	mu.Lock()
	ticketsPerRound := 1000 // max tickets per "round" (availability test)

	// Reset counter based on current global round
	globalRound := int(ticketCounter.Load()) / ticketsPerRound
	idx := (globalRound % len(nodes)) * ticketsPerRound + (nextTicket % ticketsPerRound)
	nextTicket++
	mu.Unlock()

	ticketStr := fmt.Sprintf("n%d-%d", nodeNum, idx)

	return &IssuedMsg{
		InReplyTo:    json.Number(msgID),
		Ticket:       ticketStr,
	}
}

